const REQUEST_LINE_PATTERN = /^([^ ]+) +([^ ]+) +[^ ]+$/;
const HEADER_LINE_PATTERN = /^([!#$%&'*+.^_`|~0-9A-Za-z-]+):[ \t]*(.*?)[ \t]*$/;
const CONTENT_LENGTH_PATTERN = /^\d+$/;

// Parses the head of a request (request line plus headers, without the final blank line).
// Returns { method, target, path, headers, contentLength }, or null if the head is malformed.
const parseRequestHead = (head) => {
  const [requestLine, ...headerLines] = head.split('\r\n');

  const requestLineMatch = REQUEST_LINE_PATTERN.exec(requestLine);
  if (!requestLineMatch) return null;
  const [, method, target] = requestLineMatch;

  const headers = new Map();
  for (const headerLine of headerLines) {
    const headerMatch = HEADER_LINE_PATTERN.exec(headerLine);
    if (!headerMatch) return null;
    const [, name, value] = headerMatch;
    const key = name.toLowerCase();
    headers.set(key, headers.has(key) ? `${headers.get(key)}, ${value}` : value);
  }

  // Chunked and other transfer codings are not supported.
  if (headers.has('transfer-encoding')) return null;

  let contentLength = 0;
  if (headers.has('content-length')) {
    const contentLengthValue = headers.get('content-length');
    if (!CONTENT_LENGTH_PATTERN.test(contentLengthValue)) return null;
    contentLength = Number(contentLengthValue);
    if (!Number.isSafeInteger(contentLength)) return null;
  }

  const queryStart = target.indexOf('?');
  const path = queryStart === -1 ? target : target.slice(0, queryStart);

  return { method, target, path, headers, contentLength };
};

module.exports = { parseRequestHead };

